import { cva, type VariantProps } from "class-variance-authority"

export const textareaVariants = cva(
  "flex field-sizing-content min-h-16 w-full rounded-lg border border-input bg-transparent px-2.5 py-2 text-base transition-colors outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&[readonly]]:border-border [&[readonly]]:bg-muted",
  {
    variants: {
      variant: {
        outline: "border-border hover:border-input",
        filled: "border-border bg-muted hover:border-input dark:bg-muted",
        underline:
          "rounded-none border-0 border-b border-input bg-transparent px-0 dark:bg-transparent",
        ghost:
          "border-transparent bg-transparent hover:bg-muted/50 dark:bg-transparent",
      },
    },
    defaultVariants: { variant: "outline" },
  }
)

export type TextareaVariants = VariantProps<typeof textareaVariants>
export type TextareaVariant = NonNullable<TextareaVariants["variant"]>

import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from "@angular/core"

import { cn } from "@/lib/utils"

import { textareaVariants, type TextareaVariant } from "./textarea.variants"

/**
 * Angular port of @force-ui/textarea (radix-force-ui style).
 *
 * Attribute selector on a native <textarea> — usage:
 *   <textarea uiTextarea placeholder="Write a message…"></textarea>
 *   <textarea uiTextarea variant="filled" [resizable]="false"></textarea>
 */
@Component({
  selector: "textarea[uiTextarea]",
  standalone: true,
  template: "",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "data-slot": "textarea",
    "[attr.data-variant]": "variant()",
    "[class]": "classes()",
  },
})
export class TextareaComponent {
  readonly variant = input<TextareaVariant>("outline")
  readonly resizable = input(true, { transform: booleanAttribute })
  readonly className = input<string | undefined>(undefined, { alias: "class" })

  protected readonly classes = computed(() =>
    cn(
      textareaVariants({ variant: this.variant() }),
      this.resizable() ? "resize-y" : "resize-none",
      this.className()
    )
  )
}

export { TextareaComponent as Textarea } from "./textarea.component"
export {
  textareaVariants,
  type TextareaVariants,
  type TextareaVariant,
} from "./textarea.variants"
